from collections import deque

class Solution:
    def racecar(self, target: int) -> int:
        start = (0, 1)
        q = deque([start])
        seen = {start}
        steps = 0
        while q:
            for _ in range(len(q)):
                p, s = q.popleft()
                if p == target:
                    return steps
                for np, ns in ((p + s, 2 * s), (p, -1 if s > 0 else 1)):
                    if abs(np) <= 2 * target and (np, ns) not in seen:
                        seen.add((np, ns))
                        q.append((np, ns))
            steps += 1
        return -1

