#include <queue>
#include <unordered_set>
using namespace std;

class Solution {
public:
    int racecar(int target) {
        queue<pair<long long,long long>> q;
        unordered_set<long long> seen;
        auto enc = [](long long p, long long s){ return (p << 20) ^ (s & ((1LL<<20)-1)); };
        q.push({0, 1});
        seen.insert(enc(0, 1));
        long long T = target;
        int steps = 0;
        while (!q.empty()) {
            int sz = q.size();
            while (sz--) {
                auto [p, s] = q.front(); q.pop();
                if (p == T) return steps;
                vector<pair<long long,long long>> nxt = {{p + s, 2 * s}, {p, s > 0 ? -1 : 1}};
                for (auto& st : nxt) {
                    if (llabs(st.first) <= 2 * T && !seen.count(enc(st.first, st.second))) {
                        seen.insert(enc(st.first, st.second));
                        q.push(st);
                    }
                }
            }
            steps++;
        }
        return -1;
    }
};

