import java.util.*;

class Solution {
    public int racecar(int target) {
        Deque<long[]> q = new ArrayDeque<>();
        Set<Long> seen = new HashSet<>();
        q.add(new long[]{0, 1});
        seen.add(key(0, 1));
        long T = target;
        int steps = 0;
        while (!q.isEmpty()) {
            int sz = q.size();
            while (sz-- > 0) {
                long[] cur = q.poll();
                long p = cur[0], s = cur[1];
                if (p == T) return steps;
                long[][] nxt = {{p + s, 2 * s}, {p, s > 0 ? -1 : 1}};
                for (long[] st : nxt) {
                    if (Math.abs(st[0]) <= 2 * T && seen.add(key(st[0], st[1]))) {
                        q.add(st);
                    }
                }
            }
            steps++;
        }
        return -1;
    }
    private long key(long p, long s) { return (p << 20) ^ (s & ((1L << 20) - 1)); }
}

