var racecar = function(target) {
    const key = (p, s) => p * 100000 + (s > 0 ? s : 50000 - s);
    let q = [[0, 1]];
    let seen = new Set([key(0, 1)]);
    let steps = 0;
    while (q.length) {
        const next = [];
        for (const [p, s] of q) {
            if (p === target) return steps;
            const cands = [[p + s, 2 * s], [p, s > 0 ? -1 : 1]];
            for (const [np, ns] of cands) {
                if (Math.abs(np) <= 2 * target && !seen.has(key(np, ns))) {
                    seen.add(key(np, ns));
                    next.push([np, ns]);
                }
            }
        }
        q = next;
        steps++;
    }
    return -1;
};

