from functools import lru_cache

class Solution:
    def racecar(self, target: int) -> int:
        @lru_cache(None)
        def dp(t):
            if t == 0:
                return 0
            n = t.bit_length()
            if (1 << n) - 1 == t:
                return n
            res = n + 1 + dp((1 << n) - 1 - t)
            for m in range(n - 1):
                res = min(res, n + 1 + m + 1 + dp(t - (1 << (n - 1)) + 1 + (1 << m) - 1))
            return res
        return dp(target)

