#include <vector>
#include <cstring>
using namespace std;

class Solution {
    vector<int> memo;
    int dp(int t) {
        if (t == 0) return 0;
        if (memo[t] != -1) return memo[t];
        int n = 32 - __builtin_clz(t);
        if ((1 << n) - 1 == t) return memo[t] = n;
        int res = n + 1 + dp((1 << n) - 1 - t);
        for (int m = 0; m < n - 1; m++)
            res = min(res, n + 1 + m + 1 + dp(t - (1 << (n - 1)) + 1 + (1 << m) - 1));
        return memo[t] = res;
    }
public:
    int racecar(int target) {
        memo.assign(target + 1, -1);
        return dp(target);
    }
};

