class Solution {
    private int[] memo;
    public int racecar(int target) {
        memo = new int[target + 1];
        java.util.Arrays.fill(memo, -1);
        return dp(target);
    }
    private int dp(int t) {
        if (t == 0) return 0;
        if (memo[t] != -1) return memo[t];
        int n = 32 - Integer.numberOfLeadingZeros(t);
        if ((1 << n) - 1 == t) return memo[t] = n;
        int res = n + 1 + dp((1 << n) - 1 - t);
        for (int m = 0; m < n - 1; m++)
            res = Math.min(res, n + 1 + m + 1 + dp(t - (1 << (n - 1)) + 1 + (1 << m) - 1));
        return memo[t] = res;
    }
}

