var racecar = function(target) {
    const memo = new Array(target + 1).fill(-1);
    const dp = (t) => {
        if (t === 0) return 0;
        if (memo[t] !== -1) return memo[t];
        let n = 1;
        while ((1 << n) - 1 < t) n++;
        if ((1 << n) - 1 === t) return (memo[t] = n);
        let res = n + 1 + dp((1 << n) - 1 - t);
        for (let m = 0; m < n - 1; m++)
            res = Math.min(res, n + 1 + m + 1 + dp(t - (1 << (n - 1)) + 1 + (1 << m) - 1));
        return (memo[t] = res);
    };
    return dp(target);
};
